        font-size: 18px !important;
    }

    #video-title.ytd-rich-grid-media{
        font-size: 1.42rem;
    }

    ytd-grid-video-renderer #video-title.yt-simple-endpoint.ytd-grid-video-renderer {
        font-weight: initial;
    }

    #video-title.ytd-compact-video-renderer {
        font-weight: 350;
        font-family: var(--vknDefaultFontFamily) !important;
        font-size: 13px;
    }

    #content-text.ytd-comment-renderer,
    span.style-scope.yt-formatted-string {
        --yt-endpoint-color: var(--yt-spec-call-to-action);
        --yt-endpoint-hover-color: var(--yt-spec-call-to-action);
        --yt-endpoint-visited-color: var(--yt-spec-call-to-action);
        color: var(--yt-spec-text-primary);
        font-family: var(--vknMonoFontFamily) !important;
        line-height: 2rem;
        font-weight: 100 !important;
    }

    .ytd-comment-view-model > * {
        font-family: var(--vknMonoFontFamily) !important;
    }

    #description.ytd-video-secondary-info-renderer {
